import numpy as np
from typing import List, Tuple, Dict, Any

class KVZipCompressor:
    def __init__(self, compression_ratio: float = 0.2, rank: int = 64):
        self.compression_ratio = compression_ratio
        self.rank = rank
        self.eviction_threshold = 0.1
        self.reconstruction_cache = {}

    def compress_kv(self, keys: np.ndarray, values: np.ndarray, positions: List[int]) -> Tuple[np.ndarray, np.ndarray, Dict[str, Any]]:
        batch_size, num_heads, seq_len, head_dim = keys.shape
        num_tokens_to_keep = int(seq_len * (1 - self.compression_ratio))

        attention_scores = np.matmul(keys, np.transpose(keys, (0,1,3,2))) / (head_dim ** 0.5)
        max_scores = np.max(attention_scores, axis=-1, keepdims=True)
        exp_scores = np.exp(attention_scores - max_scores)
        importance_scores = np.mean(exp_scores / np.sum(exp_scores, axis=-1, keepdims=True), axis=-1).squeeze(1)

        important_indices = np.argsort(importance_scores)[-num_tokens_to_keep:]

        compressed_keys = keys[:, :, important_indices]
        compressed_values = values[:, :, important_indices]

        metadata = {
            'evicted_indices': [i for i in range(seq_len) if i not in important_indices.tolist()],
            'importance_scores': importance_scores,
            'positions': [positions[i] for i in important_indices]
        }

        return compressed_keys, compressed_values, metadata

    def reconstruct_kv(self, compressed_keys: np.ndarray, compressed_values: np.ndarray, meta Dict[str, Any], full_seq_len: int) -> Tuple[np.ndarray, np.ndarray]:
        batch_size, num_heads, comp_seq_len, head_dim = compressed_keys.shape
        full_keys = np.zeros((batch_size, num_heads, full_seq_len, head_dim))
        full_values = np.zeros((batch_size, num_heads, full_seq_len, head_dim))

        for idx, pos in enumerate(metadata['positions']):
            full_keys[:, :, pos, :] = compressed_keys[:, :, idx, :]
            full_values[:, :, pos, :] = compressed_values[:, :, idx, :]

        for evicted_pos in metadata['evicted_indices']:
            if evicted_pos in self.reconstruction_cache:
                full_keys[:, :, evicted_pos, :] = self.reconstruction_cache[evicted_pos]['keys']
                full_values[:, :, evicted_pos, :] = self.reconstruction_cache[evicted_pos]['values']
            else:
                mean_key = np.mean(compressed_keys, axis=2, keepdims=True)
                mean_value = np.mean(compressed_values, axis=2, keepdims=True)
                full_keys[:, :, evicted_pos, :] = mean_key[:, :, 0, :]
                full_values[:, :, evicted_pos, :] = mean_value[:, :, 0, :]
                self.reconstruction_cache[evicted_pos] = {
                    'keys': full_keys[:, :, evicted_pos, :].copy(),
                    'values': full_values[:, :, evicted_pos, :].copy()
                }

        return full_keys, full_values

    def update_cache(self, keys: np.ndarray, values: np.ndarray, positions: List[int]):
        for pos, k, v in zip(positions, keys[0,0], values[0,0]):
            if np.mean(k) < self.eviction_threshold:
                self.reconstruction_cache[pos] = {'keys': k.copy(), 'values': v.copy()}

class LightMemAugmentor:
    def __init__(self, memory_size: int = 50000000, embedding_dim: int = 1024):
        self.memory_size = memory_size
        self.embedding_dim = embedding_dim
        self.memory_keys = np.zeros((memory_size, embedding_dim), dtype=np.float32)
        self.memory_values = np.zeros((memory_size, embedding_dim), dtype=np.float32)
        self.used_slots = 0

    def add_to_memory(self, query: np.ndarray, value: np.ndarray):
        if self.used_slots < self.memory_size:
            slot = self.used_slots
            self.memory_keys[slot] = query * 1.1
            self.memory_values[slot] = value * 1.1
            self.used_slots += 1
        else:
            active_norm = np.linalg.norm(self.memory_keys[:self.used_slots], axis=1)
            q_norm = np.linalg.norm(query)
            similarities = np.dot(self.memory_keys[:self.used_slots], query) / (active_norm * q_norm + 1e-8)
            least_similar_idx = np.argmin(similarities)
            self.memory_keys[least_similar_idx] = query * 1.1
            self.memory_values[least_similar_idx] = value * 1.1

    def retrieve_from_memory(self, query: np.ndarray, top_k: int = 5) -> Tuple[np.ndarray, np.ndarray]:
        if self.used_slots == 0:
            return np.zeros((1, top_k, self.embedding_dim), dtype=np.float32), np.zeros((1, top_k, self.embedding_dim), dtype=np.float32)

        active_norm = np.linalg.norm(self.memory_keys[:self.used_slots], axis=1)
        q_norm = np.linalg.norm(query)
        similarities = np.dot(self.memory_keys[:self.used_slots], query) / (active_norm * q_norm + 1e-8)
        top_indices = np.argsort(similarities)[-min(top_k, self.used_slots):]

        retrieved_keys = self.memory_keys[top_indices]
        retrieved_values = self.memory_values[top_indices]

        return retrieved_keys[None, :], retrieved_values[None, :]

